<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Notification Preferences</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f4f7fb;
      --card: #ffffff;
      --text: #142033;
      --muted: #5d6b82;
      --border: #d9e1ee;
      --primary: #4f46e5;
      --primary-soft: #eef2ff;
      --shadow: 0 24px 60px rgba(20, 32, 51, 0.12);
      --radius: 20px;
    }

    * {
      box-sizing: border-box;
    }

    html {
      min-height: 100%;
      background:
        radial-gradient(circle at top, rgba(79, 70, 229, 0.12), transparent 38%),
        linear-gradient(180deg, #eef3ff 0%, var(--bg) 45%, #f8fafc 100%);
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      line-height: 1.5;
    }

    a {
      color: inherit;
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: var(--text);
      color: #fff;
      text-decoration: none;
      transform: translateY(-180%);
      transition: transform 160ms ease;
      z-index: 10;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    .page {
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 2rem;
    }

    .card {
      width: min(100%, 42rem);
      background: rgba(255, 255, 255, 0.88);
      backdrop-filter: blur(16px);
      border: 1px solid rgba(217, 225, 238, 0.9);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      padding: clamp(1.5rem, 4vw, 2.5rem);
    }

    h1 {
      margin: 0 0 0.5rem;
      font-size: clamp(1.75rem, 4vw, 2.5rem);
      line-height: 1.1;
      letter-spacing: -0.03em;
    }

    .intro {
      margin: 0 0 1.5rem;
      color: var(--muted);
      max-width: 34rem;
    }

    .form-field {
      margin: 0 0 1.5rem;
    }

    fieldset {
      margin: 0;
      padding: 0;
      border: 0;
      min-inline-size: 0;
    }

    legend {
      padding: 0;
      margin: 0 0 0.75rem;
      font-size: 1.05rem;
      font-weight: 700;
      line-height: 1.3;
    }

    .required {
      color: #b42318;
      margin-left: 0.2rem;
    }

    .help {
      margin: 0 0 1rem;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .radio-list {
      display: grid;
      gap: 0.75rem;
    }

    .radio-option {
      display: grid;
      grid-template-columns: 1.15rem 1fr;
      gap: 0.9rem;
      align-items: center;
      padding: 1rem 1.1rem;
      border: 1px solid var(--border);
      border-radius: 16px;
      background: #fff;
      transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease, background-color 160ms ease;
    }

    .radio-option:hover {
      border-color: #b9c5e7;
      transform: translateY(-1px);
    }

    .radio-option:focus-within {
      border-color: var(--primary);
      box-shadow: 0 0 0 4px rgba(79, 70, 229, 0.16);
    }

    .radio-option input {
      margin: 0;
      width: 1.1rem;
      height: 1.1rem;
      accent-color: var(--primary);
    }

    .radio-option label {
      cursor: pointer;
      font-weight: 600;
    }

    .actions {
      display: flex;
      flex-wrap: wrap;
      gap: 1rem;
      align-items: center;
    }

    button {
      appearance: none;
      border: 0;
      border-radius: 999px;
      padding: 0.95rem 1.35rem;
      background: linear-gradient(135deg, #4f46e5, #7c3aed);
      color: #fff;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      box-shadow: 0 14px 30px rgba(79, 70, 229, 0.25);
      transition: transform 160ms ease, box-shadow 160ms ease, filter 160ms ease;
    }

    button:hover {
      transform: translateY(-1px);
      filter: brightness(1.03);
    }

    button:focus-visible,
    .radio-option input:focus-visible {
      outline: 3px solid #111827;
      outline-offset: 3px;
    }

    .status {
      min-height: 1.5rem;
      margin: 0;
      color: var(--muted);
    }

    .status[data-state="error"] {
      color: #b42318;
    }

    @media (max-width: 480px) {
      .page {
        padding: 1rem;
      }

      .card {
        border-radius: 18px;
      }

      .radio-option {
        grid-template-columns: 1rem 1fr;
        padding: 0.9rem 0.95rem;
      }
    }

    @media (forced-colors: active) {
      .skip-link,
      .card,
      .radio-option,
      button {
        forced-color-adjust: auto;
      }

      .radio-option:focus-within,
      button:focus-visible,
      .radio-option input:focus-visible {
        outline: 2px solid CanvasText;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>

  <main id="main-content" class="page">
    <section class="card" aria-labelledby="notification-title">
      <h1 id="notification-title">Notification preferences</h1>
      <p class="intro">Choose the single channel you want us to use when sending updates.</p>

      <form id="notification-form" novalidate>
        <div class="form-field">
          <fieldset aria-describedby="notification-help">
            <legend>How do you prefer to receive notifications? <span class="required" aria-hidden="true">*</span></legend>
            <p id="notification-help" class="help">Select one option before saving your preference.</p>

            <div class="radio-list">
              <div class="radio-option">
                <input id="notification-email" type="radio" name="notification-preference" value="Email" required>
                <label for="notification-email">Email</label>
              </div>

              <div class="radio-option">
                <input id="notification-sms" type="radio" name="notification-preference" value="SMS" required>
                <label for="notification-sms">SMS</label>
              </div>

              <div class="radio-option">
                <input id="notification-push" type="radio" name="notification-preference" value="Push Notifications" required>
                <label for="notification-push">Push Notifications</label>
              </div>
            </div>
          </fieldset>
        </div>

        <div class="actions">
          <button type="submit">Save preference</button>
          <p class="status" id="form-status" role="status" aria-live="polite"></p>
        </div>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById('notification-form');
    const status = document.getElementById('form-status');

    form.addEventListener('submit', (event) => {
      event.preventDefault();

      if (!form.checkValidity()) {
        status.textContent = 'Error: Choose how you want to receive notifications.';
        status.dataset.state = 'error';
        form.reportValidity();
        return;
      }

      const selection = form.elements['notification-preference'].value;
      status.textContent = `Saved: ${selection}.`;
      status.dataset.state = 'success';
    });
  </script>
</body>
</html>
